//! Every page in this file was written by the frozen TypeScript prototype, not
//! by the Rust code it checks.
//!
//! `tests/data/pages-expected.json` was generated by
//! `tests/oracle/gen-pages-expected.ts`, which ran the frozen prototype
//! **as a program** over small synthetic IR trees and recorded the tree of pages
//! it produced.
//!
//! **The fixture is a frozen value: HEAD has no way to regenerate it.** The
//! generator and the prototype it drove were removed with `experiments/` on
//! 2026-08-16 and exist only at tag `experiments-frozen`.
//!
//! # Why a program and not a slice
//!
//! The other oracles in this crate slice a function out of the prototype and
//! call it. What M1-d3 ports is the prototype's *top level*: the order the name
//! maps are built in, the site-wide suppressed set, and which modules get a
//! page. Slicing that would mean re-implementing it in order to test it.
//!
//! # M8-b: what a page *says*, not the bytes it says it in
//!
//! Up to M7 the comparison was `got == want` over whole pages. M8-b rewrote the
//! markup on purpose (`docs/plans/ui-redesign.md`), so gate A is finished (plan
//! §1) and that comparison cannot hold. What is compared instead is
//! [`PageContent`] — and it is chosen to be exactly this file's own subject:
//!
//! | | how |
//! |---|---|
//! | which modules got a page | the paths, unchanged |
//! | which items are on it and in what order | the ordered list of declaration anchors and module docstrings |
//! | what a module docstring rendered to | **byte for byte** — M8 did not touch `lean-doc-md` |
//! | where the page links | the hrefs out of `main`, plus the two things M8-b moved *into* it |
//!
//! The declaration blocks themselves are `tests/page_parts.rs`'s subject and are
//! compared there; a page is checked for having the right ones in the right
//! order, not for their insides. **This is weaker than the byte comparison it
//! replaces**: markup inside a block can move without failing here.
//!
//! # What this file does **not** stand on
//!
//! The real corpus. That is [`pages_carry_the_reference_trees_content`]
//! (env-gated) and `tools/render-compare.sh`, which compare all 432 pages
//! against the prototype's own output, and
//! [`pages_carry_the_doc_gen4_trees_declarations`], which is the one oracle here
//! that this repository did not write. The cases below exist to reach the
//! corners the corpus has none of.
//!
//! # Eight of the twenty-one branches never fire on the real corpus
//!
//! 【実測, `branchTotals`】 — the corpus has no module without imports, no
//! module name needing HTML escaping, no `_private.` declaration, and no
//! module docstring sharing a position with a declaration. The last one is the
//! whole difference between the page order's real tie-breaker and the obvious
//! wrong one, and it is invisible to all 432 pages.

#![expect(
    clippy::case_sensitive_file_extension_comparisons,
    reason = "reproduces the prototype's `endsWith`, which is the thing being checked"
)]

use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::{Path, PathBuf};

use lean_doc_render::{
    ExternalLinks, ModuleSet, RenderOptions, escape_html, page_path, render_site,
};
use serde::Deserialize;

mod common;
use common::{Tally, rewrite_source_path_anchors};

const FIXTURE: &str = include_str!("data/pages-expected.json");

const DEFAULT_IR: &str = "/private/tmp/lean-doc-relay/w7h/base-ir";
const DEFAULT_LINK_INDEX: &str = "/private/tmp/lean-doc-relay/w7c/linkindex/link-index.lidx";
const DEFAULT_REFERENCE: &str = "/private/tmp/lean-doc-relay/m1/ref-pages";
/// doc-gen4's own output on the measurement target. Inside the target's
/// `.lake`, which is gitignored there and never written to from here.
const DEFAULT_DOCGEN4_TREE: &str = "/Users/haruka/dev/lean-projects/.lake/build/doc";

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Expected {
    oracle: String,
    /// 40 hex digits, or `coverage.ts` scores the tree lower (plan 決定 1).
    source_url: String,
    ir_modules: usize,
    ir_declarations: usize,
    page_declarations: usize,
    suppressed_declarations: usize,
    /// How often each branch fires in one full run of the target package.
    branch_totals: BTreeMap<String, u64>,
    /// How many curated cases reach each branch.
    curated_branches: BTreeMap<String, u64>,
    /// The branches with a zero in `branch_totals`, as the generator listed
    /// them. Stored as well as derivable so a disagreement is itself a failure.
    never_fires: BTreeSet<String>,
    cases: Vec<Case>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Case {
    what: String,
    branches: Vec<String>,
    /// Set when the prototype's answer is the one that is wrong.
    note: Option<String>,
    /// The IR tree as bytes, keyed by path under its root.
    ir: BTreeMap<String, String>,
    lidx: String,
    link_index: bool,
    /// `null` = the run passed no `--only`; `[]` = a render set that came out
    /// empty, which the prototype cannot express.
    only: Option<Vec<String>>,
    /// The pages the prototype wrote, keyed by path under the site root.
    pages: BTreeMap<String, String>,
}

fn expected() -> Expected {
    serde_json::from_str(FIXTURE).expect("tests/data/pages-expected.json is valid")
}

#[test]
fn fixture_is_the_prototypes_own_output() {
    let e = expected();
    assert!(e.oracle.contains("render.ts"), "{}", e.oracle);
    assert!(e.oracle.contains("as a program"), "{}", e.oracle);
    assert!(e.cases.len() >= 12, "only {} cases", e.cases.len());
    let rev = e
        .source_url
        .rsplit_once("/blob/")
        .expect("the source URL is a /blob/<rev> prefix")
        .1;
    assert_eq!(rev.len(), 40, "{rev} is not a 40-hex revision");
    assert!(rev.bytes().all(|b| b.is_ascii_hexdigit()), "{rev}");
}

/// The comparison this file exists for.
///
/// One case is a recorded **disagreement**: `render.ts` cannot say "render no
/// modules", so its answer to an empty render set is every page. That case is
/// checked the other way round — see [`an_empty_render_set_renders_nothing`].
#[test]
fn every_case_carries_the_prototypes_page_content() {
    let e = expected();
    let mut failures = Vec::new();
    let mut compared = 0usize;
    let mut items = 0usize;
    let mut dangling = 0usize;
    for case in &e.cases {
        if case.only.as_ref().is_some_and(Vec::is_empty) {
            continue;
        }
        let work = TempDir::new(&case.what);
        let got = case.render(&work);
        if got.keys().collect::<Vec<_>>() != case.pages.keys().collect::<Vec<_>>() {
            failures.push(format!(
                "{}: different files\n  want: {:?}\n  got:  {:?}",
                case.what,
                case.pages.keys().collect::<Vec<_>>(),
                got.keys().collect::<Vec<_>>()
            ));
            continue;
        }
        let site = case.site_pages();
        for (path, want) in &case.pages {
            let want =
                PageContent::prototype(want).without_links_to_absent_pages(&site, &mut dangling);
            items += want.items.len();
            if let Err(why) = want.matches(&PageContent::of(&got[path])) {
                failures.push(format!("{} {path}: {why}", case.what));
            }
        }
        compared += case.pages.len();
    }
    assert!(
        failures.is_empty(),
        "{} of {} cases differ from the prototype:\n{}",
        failures.len(),
        e.cases.len(),
        failures.join("\n")
    );
    assert!(compared >= 14, "only {compared} pages were compared");
    // The rewrite above is the one place this oracle is *re-answered* rather
    // than trusted, so it has to keep firing: at zero it would be comparing the
    // prototype's bytes unchanged and this test would say nothing about the
    // 2026-08-17 rule 【実測: 4 over the committed cases】.
    assert!(
        dangling >= 4,
        "only {dangling} of the prototype's links pointed at a page it did not write"
    );
    // A `PageContent` that came out empty on both sides would pass every
    // comparison above, so the extractor is held to finding something.
    // 【実測 2026-08-16: 19 items over the committed cases】
    assert!(items >= 15, "only {items} page items were compared");
}

/// The hole plan §5 names: `render.ts:2088` reads the module filter off the
/// *presence* of a repeated flag, so a render set that came out empty means
/// "every module". The incremental pipeline had to guard the call in shell
/// (`incremental.sh:367`), and with revisions out of the bytes an empty set is
/// the common case.
///
/// The fixture records what the prototype does. This test asserts the port does
/// not, which is the one place in the suite where "differs from the oracle" is
/// the passing outcome.
#[test]
fn an_empty_render_set_renders_nothing() {
    let e = expected();
    let case = e
        .cases
        .iter()
        .find(|c| c.only.as_ref().is_some_and(Vec::is_empty))
        .expect("the fixture records the prototype's answer to an empty render set");
    assert!(
        case.pages.len() >= 2,
        "the prototype rendered {} pages; if it ever renders none this test proves nothing",
        case.pages.len()
    );
    assert!(
        case.note
            .as_deref()
            .is_some_and(|n| n.contains("every module"))
    );

    let work = TempDir::new(&case.what);
    let got = case.render(&work);
    assert!(
        got.is_empty(),
        "an empty ModuleSet wrote {} pages: {:?}",
        got.len(),
        got.keys().collect::<Vec<_>>()
    );
}

/// What the corpus is, pinned so a number quoted elsewhere traces to a run of
/// the generator rather than to a memory of one.
///
/// Every count is an event of **one full run** of the target package — no
/// `--only`, with a `.lidx` — so they can be compared with one another.
#[test]
fn the_corpus_numbers_are_what_was_measured() {
    let e = expected();
    assert_eq!(e.ir_modules, 432);
    assert_eq!(e.ir_declarations, 4_750);
    assert_eq!(e.page_declarations, 4_560);
    // 実測. `render.ts:2042` says 186 in a comment; that number is older than
    // this IR.
    assert_eq!(e.suppressed_declarations, 190);
    assert_eq!(
        e.branch_totals,
        BTreeMap::from(
            [
                // page items
                ("moduleDocItems", 1_515),
                ("pageDeclItems", 4_560),
                ("suppressedSkipped", 190),
                ("moduleWithoutModuleDocs", 8),
                ("moduleWithoutPageEntries", 26),
                ("moduleWithoutImports", 0),
                ("emptyPage", 1),
                // page order
                ("docAfterFirstDecl", 831),
                ("tieDocVsDecl", 0),
                ("tieDeclVsDecl", 2),
                // paths and names
                ("topLevelPagePath", 1),
                ("nestedPagePath", 431),
                ("moduleNameNeedsEscaping", 0),
                ("privateNameSkipped", 0),
                // the run's inputs
                ("depMapEntries", 3),
                ("linkIndexUsed", 1),
                ("linkIndexAbsent", 0),
                ("onlyAll", 432),
                ("onlyThese", 0),
                ("onlySkipped", 0),
                ("emptyOnly", 0),
            ]
            .map(|(k, n)| (k.to_owned(), n))
        ),
        "the branch profile of the corpus changed"
    );

    // Cross-checks between counters that have to agree by construction.
    assert_eq!(
        e.branch_totals["pageDeclItems"] + e.branch_totals["suppressedSkipped"],
        e.ir_declarations as u64
    );
    assert_eq!(
        e.branch_totals["topLevelPagePath"] + e.branch_totals["nestedPagePath"],
        e.ir_modules as u64,
        "every module's page goes somewhere"
    );
    assert_eq!(
        e.branch_totals["onlyAll"], e.ir_modules as u64,
        "the profile is a full run"
    );
    // The interleaving is real: 831 module docstrings sort after a declaration,
    // so "the docstrings first, then the declarations" would be a different
    // page and not a different ordering of the same one.
    assert!(e.branch_totals["docAfterFirstDecl"] > 0);
}

/// The eight branches no module of the target package reaches, and the fact
/// that the curated cases do reach them.
#[test]
fn the_curated_cases_cover_what_the_package_does_not() {
    let e = expected();
    let never: BTreeSet<String> = e
        .branch_totals
        .iter()
        .filter(|(_, n)| **n == 0)
        .map(|(k, _)| k.clone())
        .collect();
    assert_eq!(
        never, e.never_fires,
        "the generator and the totals disagree about which branches are dead"
    );
    assert_eq!(
        never,
        BTreeSet::from(
            [
                // A module docstring never shares a position with a
                // declaration in this package, so the page order's tie-breaker
                // — a running sequence number rather than `Decl::index` — is
                // invisible to all 432 pages.
                "tieDocVsDecl",
                "moduleNameNeedsEscaping",
                "moduleWithoutImports",
                "privateNameSkipped",
                // The three shapes of the module filter that a full run is not.
                "onlyThese",
                "onlySkipped",
                "emptyOnly",
                // The product always passes a `.lidx` (plan 決定 4).
                "linkIndexAbsent",
            ]
            .map(str::to_owned)
        ),
        "which branches the target package never reaches has changed"
    );
    for branch in &never {
        assert!(
            e.curated_branches.get(branch).copied().unwrap_or(0) > 0,
            "{branch} fires nowhere in the corpus and nowhere in the curated cases either"
        );
    }
    let all: BTreeSet<&String> = e.branch_totals.keys().collect();
    let curated: BTreeSet<&String> = e
        .curated_branches
        .iter()
        .filter(|(_, n)| **n > 0)
        .map(|(k, _)| k)
        .collect();
    assert_eq!(all, curated, "the curated cases stopped covering a branch");
}

/// The sample has to keep reaching every shape, read off the **fixture's own
/// bytes** — which came from the prototype — rather than off anything this
/// crate produced.
#[test]
fn the_sample_reaches_every_shape() {
    let e = expected();
    let pages = || e.cases.iter().flat_map(|c| c.pages.iter());
    let any = |what: &str, p: &dyn Fn(&String, &String) -> bool| {
        assert!(
            pages().any(|(path, html)| p(path, html)),
            "no page with {what}"
        );
    };

    any("a page at the site root", &|path, _| !path.contains('/'));
    any("a page four directories down", &|path, _| {
        path.matches('/').count() >= 4
    });
    any("a module docstring", &|_, html| {
        html.contains("<div class=\"mod_doc\">")
    });
    any("no page entries at all", &|_, html| {
        html.contains("<main>\n</main>")
    });
    any("a declaration docstring", &|_, html| {
        html.contains("<div class=\"decl\"") && html.contains("<p>See ")
    });
    any("a link into another module", &|_, html| {
        html.contains("<a href=\".././Pkg/One.html#Pkg.One.a\">")
    });
    any("a link to a module the .lidx alone knows", &|_, html| {
        html.contains("<a href=\".././Dep/Only/Module.html\">")
    });
    any(
        "a link through the .lidx's declaration section",
        &|_, html| html.contains("<a href=\".././Dep/M.html#Dep.M.thing\">"),
    );
    any("a link through a dependency slice", &|_, html| {
        html.contains("<a href=\".././Dep/Home.html#Dep.thing\">")
    });
    any("a module name that needs escaping", &|_, html| {
        html.contains("<title>Pkg.A&lt;B&amp;C&quot;D</title>")
    });
    any("an unresolved name left as a code span", &|_, html| {
        html.contains("<p>See <code>Dep.Only.Module</code> and <code>Dep.M.thing</code>.</p>")
    });

    // The one shape the corpus cannot show: the second module docstring sorts
    // before the declaration it shares a position with.
    let tie = e
        .cases
        .iter()
        .find(|c| c.branches.iter().any(|b| b == "tieDocVsDecl"))
        .expect("a case reaches the doc/declaration tie");
    let html = tie.pages.values().next().expect("it wrote a page");
    let second_doc = html.find("the second section").expect("the docstring");
    let tied_decl = html
        .find("<div class=\"decl\" id=\"Pkg.Two.b\">")
        .expect("the declaration at the same position");
    assert!(
        second_doc < tied_decl,
        "the prototype put the declaration first; the tie-breaker in the fixture is not the one \
         being tested"
    );
}

/// **M7-c**, over the same curated corpus: the three dependency-link shapes the
/// test above reads out of the prototype's bytes, rendered again with a
/// dependency map, become that package's version-pinned source.
///
/// The oracle here is **not** the prototype and cannot be — it has no notion of
/// a dependency's revision. What is asserted instead is a property of the pair
/// of runs, which is stronger than a recorded expectation would be:
///
/// 1. take the run **with** the map and unwrap every anchor that points under
///    `Dep`'s blob URL, leaving the text it wrapped;
/// 2. what is left is the empty-map run **byte for byte** — so the map added
///    those anchors and changed nothing else, anywhere on the page;
/// 3. the URLs unwrapped are the three shapes named below;
/// 4. the empty-map run points at `Dep` nowhere at all.
///
/// **The pair is anchors appearing, not hrefs moving** (2026-08-17). Before that
/// day a link into `Dep` was a relative page link and the map replaced its
/// `href`; now the empty map draws no link — the page has a page for no module
/// of `Dep` — so what the map adds is the whole `<a>`. That is the same
/// property one level up, and it is the shape that says the dead link is gone.
///
/// So the empty-map run keeps the prototype as its oracle
/// ([`every_case_carries_the_prototypes_page_content`]) and this one says
/// exactly what the map added on top of it.
#[test]
fn a_dependency_map_moves_exactly_the_links_into_the_dependency() {
    let e = expected();
    let external = ExternalLinks::new([("Dep", DEP_BASE)]);
    let mut moved: BTreeSet<String> = BTreeSet::new();
    let mut cases_with_a_dependency_link = 0usize;

    for case in &e.cases {
        if case.only.as_ref().is_some_and(Vec::is_empty) {
            continue;
        }
        let work = TempDir::new(&case.what);
        let before = case.render(&work);
        let work = TempDir::new(&case.what);
        let after = case.render_with(&work, &external);
        assert_eq!(
            before.keys().collect::<Vec<_>>(),
            after.keys().collect::<Vec<_>>(),
            "{}: the map changed which pages exist",
            case.what
        );
        let mut touched = false;
        for (path, want) in &before {
            let (stripped, urls) = without_anchors_under(&after[path], DEP_BASE);
            assert_eq!(
                want, &stripped,
                "{} {path}: the map changed something other than the links into Dep",
                case.what
            );
            for was in split_hrefs(want).1 {
                assert!(
                    !was.contains("/Dep/"),
                    "{} {path}: a link into Dep is still a relative page link: {was}",
                    case.what
                );
            }
            for url in urls {
                assert!(
                    url.ends_with(".lean"),
                    "{} {path}: {url} is not a source file",
                    case.what
                );
                touched = true;
                moved.insert(url);
            }
        }
        if touched {
            cases_with_a_dependency_link += 1;
        }
    }

    // The three shapes `the_sample_reaches_every_shape` pins on the prototype's
    // side, by name, so a corpus that stopped exercising one of them fails here
    // rather than passing vacuously. The `.lidx` these cases carry is `#lidx1`
    // and has no ranges, so every URL is the file's — which is the fallback
    // §M7「行範囲が取れない宣言でリンクを消さない」 asks for.
    assert_eq!(
        moved.iter().map(String::as_str).collect::<Vec<_>>(),
        [
            // a link through the .lidx's declaration section (`Dep.M.thing`)
            &format!("{DEP_BASE}/Dep/M.lean"),
            // a link through a dependency slice (`Dep.thing` in `Dep.Home`)
            &format!("{DEP_BASE}/Dep/Home.lean"),
            // a module the .lidx alone knows (`Dep.Only.Module`)
            &format!("{DEP_BASE}/Dep/Only/Module.lean"),
        ]
        .map(String::as_str)
        .into_iter()
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>(),
    );
    assert!(
        cases_with_a_dependency_link >= 2,
        "only {cases_with_a_dependency_link} case(s) have a link into a dependency"
    );
}

/// All 432 pages, against the tree the prototype wrote — by content since
/// M8-b, exactly as the curated cases above.
///
/// `#[ignore]`d: the reference tree is not in this repository. This is the same
/// comparison `tools/render-compare.sh` makes; it is here so that a machine
/// that has the corpus does not need the shell script.
#[test]
#[ignore = "corpus: needs LEAN_DOC_REFERENCE_PAGES + LEAN_DOC_IR + LEAN_DOC_LINK_INDEX (tools/corpus-gate.sh)"]
fn pages_carry_the_reference_trees_content() {
    let reference = PathBuf::from(
        std::env::var("LEAN_DOC_REFERENCE_PAGES").unwrap_or_else(|_| DEFAULT_REFERENCE.into()),
    );
    let ir = PathBuf::from(std::env::var("LEAN_DOC_IR").unwrap_or_else(|_| DEFAULT_IR.into()));
    let lidx = PathBuf::from(
        std::env::var("LEAN_DOC_LINK_INDEX").unwrap_or_else(|_| DEFAULT_LINK_INDEX.into()),
    );
    // Presence is counted in **files**, not directories: `/private/tmp` is
    // swept, and an emptied `ref-pages` leaves its directory behind. `is_dir()`
    // said yes to that and the comparison then failed for an environmental
    // reason — the same trap `lean-doc-incr/tests/impact.rs` documents.
    assert!(
        file_count(&reference) != 0 && file_count(&ir) != 0 && lidx.is_file(),
        "no corpus (empty or missing: {} / {} / {}): set LEAN_DOC_REFERENCE_PAGES, LEAN_DOC_IR \
         and LEAN_DOC_LINK_INDEX, or run this test through tools/corpus-gate.sh, which is the \
         only thing that should be asking for it",
        reference.display(),
        ir.display(),
        lidx.display(),
    );
    let e = expected();
    let work = TempDir::new("reference");
    let summary = render_site(&RenderOptions {
        ir: &ir,
        pages: &work.path,
        source_url: &e.source_url,
        // M7-c: the reference tree is the **prototype's**, whose links into a
        // dependency are all relative. The empty map is what reproduces them;
        // this test is therefore an oracle for the fallback branch only, and
        // `benchmarks/results/m7c-*` is where the populated one is measured.
        external_links: &ExternalLinks::default(),
        link_index: Some(&lidx),
        only: &ModuleSet::All,
    })
    .expect("the corpus renders");
    assert_eq!(summary.pages_written, 432);
    assert_eq!(summary.declarations_rendered, 4_560);
    assert_eq!(summary.declarations_suppressed, 190);

    let want = read_tree(&reference);
    let got = read_tree(&work.path);
    assert_eq!(
        want.keys().collect::<Vec<_>>(),
        got.keys().collect::<Vec<_>>(),
        "the two trees have different files"
    );
    // **M8, gate UI-2** (`common`): a source path in a docstring is the one
    // question this crate answers differently from the prototype, so it is
    // taken out of the comparison below and counted here instead. Collapsing
    // the anchors on *both* sides needs no index — the anchor's text is the
    // path either way — and it leaves every other byte of both trees in place.
    let (mut theirs, mut ours) = (Tally::default(), Tally::default());
    let collapse =
        |tree: BTreeMap<String, String>, tally: &mut Tally| -> BTreeMap<String, String> {
            tree.into_iter()
                .map(|(path, html)| {
                    let html = rewrite_source_path_anchors(&html, &|_| None, tally);
                    (path, html)
                })
                .collect()
        };
    let want = collapse(want, &mut theirs);
    let got = collapse(got, &mut ours);
    // The prototype linked every source path it saw; this run links the ones
    // whose path names exactly one known module and leaves the rest as text. The
    // two counts are **not pinned** here: this test does not run without a
    // reference tree, so a number written into it could not be re-measured on
    // the machine that changes the rule. Where the exact counts live: the
    // sample in `tests/autolink.rs`, and the site scan in
    // `benchmarks/results/m8-ui2-dead-links.txt`.
    assert!(
        theirs.total() > 0,
        "the reference tree has no source-path link, so this normalisation \
         hides nothing and the comparison below is the old one"
    );
    assert!(
        ours.total() <= theirs.total(),
        "this run wrote {} source-path links where the prototype wrote {}; the \
         rule can only drop them",
        ours.total(),
        theirs.total()
    );
    // The one page the prototype and md4c disagree on: a broken nested code
    // span in a module docstring, where doc-gen4 sides with this crate. Pinned
    // by name and by count, so a *second* divergence fails here. It survives
    // the move to a content comparison because the divergence is *in* a module
    // docstring, and those are still compared byte for byte.
    // 【実測, plan §5 / `lean-doc-md/tests/ts_docstring.rs`】
    let differing: Vec<&String> = want
        .iter()
        .filter(|(path, html)| {
            got.get(*path).is_none_or(|got| {
                PageContent::prototype(html)
                    .matches(&PageContent::of(got))
                    .is_err()
            })
        })
        .map(|(path, _)| path)
        .collect();
    assert_eq!(
        differing,
        ["InformationTheory/Shannon/TimeBandLimiting/Count.html"],
        "the set of pages that differ from the prototype changed"
    );
}

/// The oracle that did **not** come out of this repository: doc-gen4's own tree
/// on the measurement target (`<root>/.lake/build/doc`).
///
/// Every other comparison in this crate is against `experiments/stage7d` (frozen
/// at tag `experiments-frozen`), which is a transcription this repository wrote.
/// M8-b ended the byte comparison with it, and the honest question is then
/// whether anything independent is left.
/// This is what is: two facts about a page that no UI decision can move.
///
/// | | compared |
/// |---|---|
/// | which declarations get an entry | the anchors, as a **set**; and as a sequence except where doc-gen4's own sort is unstable |
/// | what a module docstring says | its **text**, tags stripped, in order |
/// | which file a declaration's source link names | the path under `/blob/<rev>` |
///
/// # Two things this cannot compare, and why
///
/// 1. **The line ranges in the source links.** The tree on disk is older than
///    the IR: 286 of the 348 shared pages have at least one declaration whose
///    `#L…-L…` moved because the `.lean` file was edited 【実測 2026-08-16】.
///    That is source drift, not a renderer difference, and comparing it would
///    fail for a reason this suite cannot fix. The *path* is compared instead.
/// 2. **Anything about the 84 modules doc-gen4 has no page for.** They were
///    added to the package after the tree was last built.
///
/// # doc-gen4's page order is not deterministic and this says where
///
/// `Process.Module.members` finishes with `qsort ModuleMember.order`, which is
/// not stable, so two declarations at the same `(line, col)` come out in an
/// order that is a property of the run rather than of the package. Both of the
/// pages where this tree and these pages disagree are that case (auto-generated
/// `ext` / `ext_iff` and a `_def`), and the assertion below is the precise one:
/// the two orders visit the same *positions* in the same order.
#[test]
#[ignore = "corpus: needs LEAN_DOC_DOCGEN4_TREE + LEAN_DOC_IR (tools/corpus-gate.sh)"]
fn pages_carry_the_doc_gen4_trees_declarations() {
    let tree = PathBuf::from(
        std::env::var("LEAN_DOC_DOCGEN4_TREE").unwrap_or_else(|_| DEFAULT_DOCGEN4_TREE.into()),
    );
    let ir = PathBuf::from(std::env::var("LEAN_DOC_IR").unwrap_or_else(|_| DEFAULT_IR.into()));
    assert!(
        file_count(&tree) != 0 && file_count(&ir) != 0,
        "no doc-gen4 tree or IR (empty or missing: {} / {}): set LEAN_DOC_DOCGEN4_TREE and \
         LEAN_DOC_IR, or run this test through tools/corpus-gate.sh, which is the only thing \
         that should be asking for it",
        tree.display(),
        ir.display(),
    );

    // Where each declaration sits, so a disagreement about order can be told
    // apart from a disagreement about content.
    let modules = lean_doc_ir::IrTree::open(&ir)
        .expect("the IR opens")
        .load_modules()
        .expect("every module reads");
    let positions: BTreeMap<&str, BTreeMap<&str, (u32, u32)>> = modules
        .iter()
        .map(|module| {
            let decls = module
                .declarations
                .iter()
                .map(|decl| (decl.name.as_str(), (decl.line, decl.col)))
                .collect();
            (module.module.as_str(), decls)
        })
        .collect();

    let e = expected();
    let work = TempDir::new("docgen4");
    // No `.lidx`: it decides where a link into a **dependency** points, and
    // nothing compared here is such a link. Requiring one would make this
    // oracle skip on a machine that has the target checked out but no relay
    // directory, which is the machine it is most worth running on.
    render_site(&RenderOptions {
        ir: &ir,
        pages: &work.path,
        source_url: &e.source_url,
        external_links: &ExternalLinks::default(),
        link_index: None,
        only: &ModuleSet::All,
    })
    .expect("the corpus renders");

    let (mut pages, mut anchors, mut docs) = (0usize, 0usize, 0usize);
    let mut reordered: Vec<String> = Vec::new();
    let mut failures: Vec<String> = Vec::new();
    for (path, got) in read_tree(&work.path) {
        // A module doc-gen4 has no page for is one added since the tree was
        // built, not a disagreement.
        let Ok(want) = fs::read_to_string(tree.join(&path)) else {
            continue;
        };
        pages += 1;
        let module = path.trim_end_matches(".html").replace('/', ".");

        let want_ids = attr_after(&want, "<div class=\"decl\" id=\"");
        let got_ids = attr_after(&got, "<section class=\"decl\" id=\"");
        anchors += want_ids.len();
        if sorted_owned(&want_ids) != sorted_owned(&got_ids) {
            let missing: Vec<&&str> = want_ids.iter().filter(|w| !got_ids.contains(w)).collect();
            let extra: Vec<&&str> = got_ids.iter().filter(|g| !want_ids.contains(g)).collect();
            failures.push(format!(
                "{module}: the page's declarations differ\n  missing: {missing:?}\n  extra: {extra:?}"
            ));
        } else if want_ids != got_ids {
            // Only doc-gen4's unstable sort may explain this: the two orders
            // have to walk the same source positions in the same order.
            let at = |name: &str| {
                positions
                    .get(module.as_str())
                    .and_then(|m| m.get(name))
                    .copied()
            };
            if want_ids
                .iter()
                .map(|n| at(n))
                .ne(got_ids.iter().map(|n| at(n)))
            {
                failures.push(format!(
                    "{module}: the page order differs somewhere other than a tie"
                ));
            }
            reordered.push(module.clone());
        }

        let want_docs = wrapped_texts(&want, "<div class=\"mod_doc\">");
        let got_docs = wrapped_texts(&got, "<div class=\"moddoc\">");
        docs += want_docs.len();
        if want_docs != got_docs {
            failures.push(format!(
                "{module}: the module docstrings differ\n  want: {want_docs:?}\n  got:  {got_docs:?}"
            ));
        }

        // Both of doc-gen4's spellings: the per-declaration `div.gh_link` and
        // the module's own `p.gh_nav_link`, which is the only one a module with
        // no page entries has. This crate spells both as `a.src`.
        let want_files = source_files(
            &want,
            &[
                "class=\"gh_link\"><a href=\"",
                "class=\"gh_nav_link\"><a href=\"",
            ],
        );
        let got_files = source_files(&got, &["<a class=\"src\" href=\""]);
        if want_files != got_files {
            failures.push(format!(
                "{module}: the source links name different files\n  want: {want_files:?}\n  got:  {got_files:?}"
            ));
        }
    }

    assert!(
        failures.is_empty(),
        "{} of {pages} pages differ from doc-gen4's tree:\n{}",
        failures.len(),
        failures
            .iter()
            .take(10)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
    eprintln!("doc-gen4 tree: {pages} pages, {anchors} anchors, {docs} module docstrings");
    // A run that matched nothing would pass every assertion above.
    // 【実測 2026-08-16: 348 pages, 3,477 anchors, 1,232 module docstrings】
    assert!(
        pages >= 300 && anchors >= 3_000 && docs >= 1_000,
        "{pages} pages, {anchors} anchors, {docs} docstrings: the tree stopped overlapping the IR"
    );
    // Named rather than tolerated. If a third page starts disagreeing about
    // order it is a new fact and not this one.
    assert_eq!(
        reordered,
        [
            "InformationTheory.Polymatroid.Basic",
            "InformationTheory.Shannon.EntropyPower.Ext"
        ],
        "which pages doc-gen4's unstable sort put in another order has changed"
    );
}

// ------------------------------------------------------------------- helpers

impl Case {
    /// Writes the case's IR into `work`, renders it, and reads the pages back.
    ///
    /// **The empty dependency map is what makes the prototype's bytes the right
    /// expectation** (M7-c): with one, every link into `Dep` becomes that
    /// package's pinned source and the prototype — which had no such notion —
    /// stops being an oracle for those hrefs.
    /// [`a_dependency_map_moves_exactly_the_links_into_the_dependency`] is the
    /// other side.
    fn render(&self, work: &TempDir) -> BTreeMap<String, String> {
        self.render_with(work, &ExternalLinks::default())
    }

    /// **The pages this site has**: one per module of the case's IR — not per
    /// page this run wrote, because `--only` narrows the run and not the site,
    /// and the page it skipped was written by the run before it. That is the set
    /// [`lean_doc_render::NameIndex::has_page`] is, read off the same input.
    ///
    /// Escaped, because an href spells a module name the way HTML does:
    /// `Pkg.A<B&C"D` lives at `Pkg/A&lt;B&amp;C&quot;D.html`.
    fn site_pages(&self) -> BTreeSet<String> {
        self.ir
            .keys()
            .filter_map(|path| path.strip_prefix("modules/")?.strip_suffix(".json"))
            .map(|module| escape_html(&page_path(module).to_string_lossy()).into_owned())
            .collect()
    }

    fn render_with(&self, work: &TempDir, external: &ExternalLinks) -> BTreeMap<String, String> {
        let ir = work.path.join("ir");
        for (name, text) in &self.ir {
            let path = ir.join(name);
            fs::create_dir_all(path.parent().expect("every IR file is under the root"))
                .expect("the temporary tree is writable");
            fs::write(&path, text).expect("the temporary tree is writable");
        }
        let lidx = work.path.join("link-index.lidx");
        fs::write(&lidx, &self.lidx).expect("the temporary tree is writable");
        let pages = work.path.join("pages");

        let only = match &self.only {
            None => ModuleSet::All,
            Some(names) => ModuleSet::These(names.iter().cloned().collect()),
        };
        let e = expected();
        render_site(&RenderOptions {
            ir: &ir,
            pages: &pages,
            source_url: &e.source_url,
            external_links: external,
            link_index: self.link_index.then_some(lidx.as_path()),
            only: &only,
        })
        .unwrap_or_else(|e| panic!("{}: {e}", self.what));
        read_tree(&pages)
    }
}

/// What a page says, independently of the markup it says it in.
///
/// See the file heading. Everything here is a decision of `page_html`'s top
/// level — which items, in what order, and where the page points — rather than
/// of the pieces it is assembled from.
#[derive(Debug)]
struct PageContent {
    /// The page's items **in order**, which is this file's subject.
    items: Vec<Item>,
    /// The module's own source link.
    source: String,
    /// `(href, name)` per import, in order.
    imports: Vec<(String, String)>,
    /// Every link out of the page body, sorted.
    links: Vec<String>,
}

#[derive(Debug, PartialEq, Eq)]
enum Item {
    /// A module docstring's rendered HTML, compared **byte for byte**: M8 did
    /// not touch `lean-doc-md`, and this is the largest piece of a page that is
    /// still identical to the prototype's.
    Doc(String),
    /// A declaration's anchor. Its block is `tests/page_parts.rs`'s subject.
    Decl(String),
}

impl PageContent {
    /// A page the frozen prototype wrote. Its source link and its import list
    /// live in `nav.internal_nav`, outside `main`.
    fn prototype(html: &str) -> Self {
        let main = between(html, "<main>", "</main>").unwrap_or_default();
        Self {
            items: items(main, "<div class=\"mod_doc\">", "<div class=\"decl\" id=\""),
            source: html
                .find("gh_nav_link")
                .and_then(|at| attr_values(&html[at..], "href").first().copied())
                .unwrap_or_default()
                .to_owned(),
            imports: list_after(html, "<summary>Imports</summary>"),
            links: sorted(attr_values(main, "href")),
        }
    }

    /// A page this crate wrote. M8-b moved the source link into the module's
    /// heading and the import list under it, so both are inside `main` here.
    fn of(html: &str) -> Self {
        let main =
            between(html, "<main class=\"content\" id=\"content\">", "</main>").unwrap_or_default();
        Self {
            items: items(
                main,
                "<div class=\"moddoc\">",
                "<section class=\"decl\" id=\"",
            ),
            source: between(html, "<div class=\"modhead\">", "</div>")
                .and_then(|head| attr_values(head, "href").first().copied())
                .unwrap_or_default()
                .to_owned(),
            imports: list_after(html, "<div class=\"modmeta\">"),
            links: sorted(attr_values(main, "href")),
        }
    }

    /// **2026-08-17**: the prototype's answer with every link to a page it did
    /// not write taken out — which is what this crate now renders as text.
    ///
    /// The prototype linked any module it could resolve, and it resolved the
    /// whole environment: a module of a dependency, or of the package that this
    /// run does not render, got a relative `<a href>` to a file nobody created.
    /// `batteries` is where that became visible 【実測 2026-08-17】, and the
    /// three shapes below are the same bug in the curated corpus — the fixture's
    /// own page list is the proof, since `Dep/M.html` and `Pkg/One.html` are
    /// links in pages the prototype wrote and are not pages it wrote.
    ///
    /// This is a **rule**, not a list of excused cases: an href is dropped if
    /// and only if it is a relative link to an `.html` this site has no module
    /// for. A second divergence of any other shape still fails.
    fn without_links_to_absent_pages(
        mut self,
        site: &BTreeSet<String>,
        dropped: &mut usize,
    ) -> Self {
        let absent = |href: &String| {
            let path = href.split('#').next().unwrap_or_default();
            // Only relative page links: an absolute URL is somebody else's site
            // and this run's page list says nothing about it.
            if path.contains("://") || !path.ends_with(".html") {
                return false;
            }
            let mut rest = path;
            while let Some(tail) = rest.strip_prefix("../").or_else(|| rest.strip_prefix("./")) {
                rest = tail;
            }
            !site.contains(rest)
        };
        let before = self.links.len() + self.imports.len();
        self.links.retain(|href| !absent(href));
        self.imports.retain(|(href, _)| !absent(href));
        *dropped += before - self.links.len() - self.imports.len();
        self
    }

    fn matches(&self, got: &Self) -> Result<(), String> {
        if self.items != got.items {
            return Err(format!(
                "the page's items differ\n  want: {:?}\n  got:  {:?}",
                summarise(&self.items),
                summarise(&got.items)
            ));
        }
        if self.source != got.source {
            return Err(format!(
                "source link: want {}, got {}",
                self.source, got.source
            ));
        }
        if self.imports != got.imports {
            return Err(format!(
                "imports differ\n  want: {:?}\n  got:  {:?}",
                self.imports, got.imports
            ));
        }
        // The two things M8-b moved into `main`: the module's source link and
        // its import list. Everything else the body points at is the same.
        let mut want = self.links.clone();
        want.push(self.source.clone());
        want.extend(self.imports.iter().map(|(href, _)| href.clone()));
        want.sort();
        if want != got.links {
            let missing: Vec<&String> = want.iter().filter(|w| !got.links.contains(w)).collect();
            let extra: Vec<&String> = got.links.iter().filter(|g| !want.contains(g)).collect();
            return Err(format!(
                "links differ\n  missing: {missing:?}\n  extra:   {extra:?}"
            ));
        }
        Ok(())
    }
}

/// Names each item without printing a docstring's whole HTML.
fn summarise(items: &[Item]) -> Vec<String> {
    items
        .iter()
        .map(|item| match item {
            Item::Doc(html) => format!("doc({})", &html[..html.len().min(40)]),
            Item::Decl(name) => format!("decl({name})"),
        })
        .collect()
}

/// The module docstrings and the declaration anchors of `main`, interleaved in
/// document order — which is the order `page_items` decided.
fn items(main: &str, doc_open: &str, decl_open: &str) -> Vec<Item> {
    let mut out = Vec::new();
    let mut rest = main;
    loop {
        let (doc, decl) = (rest.find(doc_open), rest.find(decl_open));
        let take_doc = match (doc, decl) {
            (Some(d), Some(k)) => d < k,
            (Some(_), None) => true,
            (None, Some(_)) => false,
            (None, None) => break,
        };
        let (at, end) = if take_doc {
            // A rendered docstring contains no `<div>` (`MD_FLAG_NOHTML`), so
            // the first close is the wrapper's — the same reasoning
            // `tests/ref_pages.rs` runs on.
            let at = doc.expect("checked") + doc_open.len();
            let end = rest[at..].find("</div>").map_or(rest.len(), |e| at + e);
            out.push(Item::Doc(rest[at..end].to_owned()));
            (at, end)
        } else {
            let at = decl.expect("checked") + decl_open.len();
            let end = rest[at..].find('"').map_or(rest.len(), |e| at + e);
            out.push(Item::Decl(rest[at..end].to_owned()));
            (at, end)
        };
        debug_assert!(end >= at);
        rest = &rest[end..];
    }
    out
}

/// Every ` name="…"` value, in document order.
fn attr_values<'a>(html: &'a str, name: &str) -> Vec<&'a str> {
    let needle = format!(" {name}=\"");
    let mut out = Vec::new();
    let mut rest = html;
    while let Some(at) = rest.find(&needle) {
        let value = &rest[at + needle.len()..];
        let end = value.find('"').unwrap_or(value.len());
        out.push(&value[..end]);
        rest = &value[end..];
    }
    out
}

fn sorted(values: Vec<&str>) -> Vec<String> {
    let mut out: Vec<String> = values.into_iter().map(str::to_owned).collect();
    out.sort();
    out
}

fn between<'a>(html: &'a str, open: &str, close: &str) -> Option<&'a str> {
    let at = html.find(open)? + open.len();
    let end = html[at..].find(close)? + at;
    Some(&html[at..end])
}

/// The `(href, text)` of every `<li>` of the first `<ul>` after `from`.
fn list_after(html: &str, from: &str) -> Vec<(String, String)> {
    let Some(at) = html.find(from) else {
        return Vec::new();
    };
    let Some(list) = between(&html[at..], "<ul>", "</ul>") else {
        return Vec::new();
    };
    list.split("<li>")
        .skip(1)
        .filter_map(|item| {
            let href = (*attr_values(item, "href").first()?).to_owned();
            Some((href, text_of(item)))
        })
        .collect()
}

/// The value that follows each `marker`, up to the `"` that closes it.
fn attr_after<'a>(html: &'a str, marker: &str) -> Vec<&'a str> {
    let mut out = Vec::new();
    let mut rest = html;
    while let Some(at) = rest.find(marker) {
        let value = &rest[at + marker.len()..];
        let end = value.find('"').unwrap_or(value.len());
        out.push(&value[..end]);
        rest = &value[end..];
    }
    out
}

fn sorted_owned<'a>(values: &[&'a str]) -> Vec<&'a str> {
    let mut out = values.to_vec();
    out.sort_unstable();
    out
}

/// The text of every element opened by `open`, up to its `</div>`.
///
/// No nesting count is needed: a rendered docstring contains no `<div>`
/// (`MD_FLAG_NOHTML`), which is the same reasoning `tests/ref_pages.rs` runs on.
fn wrapped_texts(html: &str, open: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut rest = html;
    while let Some(at) = rest.find(open) {
        let from = at + open.len();
        let end = rest[from..].find("</div>").map_or(rest.len(), |e| from + e);
        out.push(text_of(&rest[from..end]));
        rest = &rest[end..];
    }
    out
}

/// The `.lean` files a page's source links name, with the revision and the line
/// range dropped — the part of those URLs that does not move when the package's
/// sources are edited.
fn source_files(html: &str, markers: &[&str]) -> BTreeSet<String> {
    markers
        .iter()
        .flat_map(|marker| attr_after(html, marker))
        .filter_map(|href| {
            let path = href.split('#').next()?;
            let after_blob = path.split_once("/blob/")?.1;
            Some(after_blob.split_once('/')?.1.to_owned())
        })
        .collect()
}

/// The text of a fragment, tags removed and whitespace collapsed.
fn text_of(html: &str) -> String {
    let mut out = String::new();
    let mut rest = html;
    loop {
        let at = rest.find('<').unwrap_or(rest.len());
        out.push_str(&rest[..at]);
        match rest[at..].find('>') {
            Some(end) => rest = &rest[at + end + 1..],
            None => break,
        }
    }
    out.split_whitespace().collect::<Vec<_>>().join(" ")
}

/// The prefix the `Dep` package's sources live under in the test below. 40 hex
/// digits, because plan 決定 1 wants one everywhere a revision reaches a URL.
const DEP_BASE: &str = "https://github.com/o/dep/blob/0123456789abcdef0123456789abcdef01234567";

/// `html` with every `<a href="<base>…">text</a>` replaced by `text`, and the
/// URLs that were unwrapped.
///
/// The inverse of what a dependency map adds to a page (2026-08-17): with no map
/// those names are bare text, so undoing the anchors is what makes the two runs
/// comparable byte for byte. Anchors never nest here — the code renderer
/// suppresses that — so the first `</a>` closes the one that was opened.
fn without_anchors_under(html: &str, base: &str) -> (String, Vec<String>) {
    let open = format!("<a href=\"{base}");
    let mut out = String::with_capacity(html.len());
    let mut urls = Vec::new();
    let mut rest = html;
    while let Some(at) = rest.find(&open) {
        out.push_str(&rest[..at]);
        let tag = &rest[at..];
        let url_end = tag[open.len()..]
            .find('"')
            .expect("an href attribute is closed")
            + open.len();
        urls.push(format!("{base}{}", &tag[open.len()..url_end]));
        let text = &tag[url_end..];
        let opened = text.find('>').expect("the tag is closed") + 1;
        let closed = text.find("</a>").expect("the anchor is closed");
        out.push_str(&text[opened..closed]);
        rest = &text[closed + "</a>".len()..];
    }
    out.push_str(rest);
    (out, urls)
}

/// Every `href="…"` in `html`, and the bytes between them.
///
/// Two documents whose `between` halves agree differ **only** inside href
/// attributes, which is the claim M7-c has to be held to.
fn split_hrefs(html: &str) -> (Vec<&str>, Vec<&str>) {
    let (mut between, mut hrefs) = (Vec::new(), Vec::new());
    let mut rest = html;
    while let Some(at) = rest.find("href=\"") {
        between.push(&rest[..at]);
        let value = &rest[at + 6..];
        let end = value.find('"').expect("an href attribute is closed");
        hrefs.push(&value[..end]);
        rest = &value[end..];
    }
    between.push(rest);
    (between, hrefs)
}

/// Regular files under `dir`, recursively. Zero for a missing directory.
fn file_count(dir: &Path) -> usize {
    let Ok(entries) = fs::read_dir(dir) else {
        return 0;
    };
    entries
        .flatten()
        .map(|entry| match entry.file_type() {
            Ok(kind) if kind.is_dir() => file_count(&entry.path()),
            Ok(kind) if kind.is_file() => 1,
            _ => 0,
        })
        .sum()
}

/// Every `.html` under `dir`, keyed by its path relative to it. A missing
/// directory is an empty tree: a run that renders nothing creates nothing.
fn read_tree(dir: &Path) -> BTreeMap<String, String> {
    let mut out = BTreeMap::new();
    fn walk(at: &Path, prefix: &str, out: &mut BTreeMap<String, String>) {
        let Ok(entries) = fs::read_dir(at) else {
            return;
        };
        for entry in entries.flatten() {
            let name = entry.file_name().to_string_lossy().into_owned();
            if entry.path().is_dir() {
                walk(&entry.path(), &format!("{prefix}{name}/"), out);
            } else if name.ends_with(".html") {
                let text = fs::read_to_string(entry.path()).expect("a page reads back");
                out.insert(format!("{prefix}{name}"), text);
            }
        }
    }
    walk(dir, "", &mut out);
    out
}

/// A directory that removes itself, so a failed run does not leave a tree of
/// pages behind. Hand-rolled rather than a dependency: it is ten lines and the
/// workspace has no other use for one.
struct TempDir {
    path: PathBuf,
}

impl TempDir {
    fn new(what: &str) -> Self {
        use std::sync::atomic::{AtomicU32, Ordering};
        static NEXT: AtomicU32 = AtomicU32::new(0);
        let slug: String = what
            .chars()
            .map(|c| if c.is_ascii_alphanumeric() { c } else { '-' })
            .take(40)
            .collect();
        let path = std::env::temp_dir().join(format!(
            "lean-doc-pages-{}-{}-{slug}",
            std::process::id(),
            NEXT.fetch_add(1, Ordering::Relaxed)
        ));
        let _ = fs::remove_dir_all(&path);
        fs::create_dir_all(&path).expect("the temporary directory is creatable");
        Self { path }
    }
}

impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.path);
    }
}
